 @PostMapping("/treatments") @PreAuthorize("hasRole('ADMIN')") public TreatmentCatalog treatment(@Valid @RequestBody TreatmentCatalogRequest r,Authentication a){TreatmentCatalog t=TreatmentCatalog.builder().name(r.name().trim()).category(treatmentCategory(r.category(),r.specialty())).specialty(r.specialty()).defaultDurationMinutes(r.defaultDurationMinutes()).referencePrice(nvl(r.referencePrice())).active(true).build();TreatmentCatalog saved=treatments.save(t);audit.log("CONFIGURACION","TreatmentCatalog",saved.getId().toString(),"CREAR",a,null,saved,null);return saved;}
 @PutMapping("/treatments/{id}") @PreAuthorize("hasRole('ADMIN')") public TreatmentCatalog updateTreatment(@PathVariable Long id,@Valid @RequestBody TreatmentCatalogRequest r,Authentication a){TreatmentCatalog t=treatments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Tratamiento no encontrado"));TreatmentCatalog before=TreatmentCatalog.builder().id(t.getId()).name(t.getName()).category(t.getCategory()).specialty(t.getSpecialty()).defaultDurationMinutes(t.getDefaultDurationMinutes()).referencePrice(t.getReferencePrice()).active(t.isActive()).build();t.setName(r.name().trim());t.setCategory(treatmentCategory(r.category(),r.specialty()));t.setSpecialty(r.specialty());t.setDefaultDurationMinutes(r.defaultDurationMinutes());t.setReferencePrice(nvl(r.referencePrice()));TreatmentCatalog saved=treatments.save(t);audit.log("CONFIGURACION","TreatmentCatalog",saved.getId().toString(),"ACTUALIZAR",a,before,saved,null);return saved;}
 @PatchMapping("/treatments/{id}/active") @PreAuthorize("hasRole('ADMIN')") public TreatmentCatalog treatmentActive(@PathVariable Long id,@RequestParam boolean value,Authentication a){TreatmentCatalog t=treatments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Tratamiento no encontrado"));boolean before=t.isActive();t.setActive(value);TreatmentCatalog saved=treatments.save(t);audit.log("CONFIGURACION","TreatmentCatalog",saved.getId().toString(),"CAMBIAR_ESTADO",a,before,value,"Catálogo de tratamientos");return saved;}
