 @PostMapping("/governance/backups") @PreAuthorize("hasRole('ADMIN')") public BackupVerification backup(@Valid @RequestBody BackupVerificationRequest r,Authentication a){BackupVerification b=BackupVerification.builder().backupName(r.backupName().trim()).scope(r.scope().trim()).location(r.location().trim()).sizeMb(r.sizeMb()).checksum(r.checksum()).status(r.status().trim()).encrypted(Boolean.TRUE.equals(r.encrypted())).offsiteCopy(Boolean.TRUE.equals(r.offsiteCopy())).completedAt(r.completedAt()).restorationTestedAt(r.restorationTestedAt()).notes(r.notes()).responsible(a.getName()).build();BackupVerification s=backups.save(b);audit.log("RESPALDOS","BackupVerification",s.getId().toString(),"REGISTRAR",a,null,s,null);return s;}
 private Map<String,Object> chairAnalytics(String chair,List<ClinicalEncounter> list,List<Map<String,Object>> appointmentHistory,LocalDate from,LocalDate to){long days=Math.max(1,ChronoUnit.DAYS.between(from,to)+1),available=days*14*60,used=list.stream().filter(e->"FINALIZADA".equals(e.getStatus())).mapToLong(e->e.getDurationMinutes()==null?60:e.getDurationMinutes()).sum();BigDecimal prod=list.stream().map(ClinicalEncounter::getProductionAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add),paid=list.stream().map(ClinicalEncounter::getPaidAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Object>m=new LinkedHashMap<>();m.put("chairName",chair);m.put("appointments",appointmentHistory.size());m.put("completed",list.stream().filter(e->"FINALIZADA".equals(e.getStatus())).count());m.put("cancelled",appointmentHistory.stream().filter(a->"CANCELADO".equalsIgnoreCase(str(a.get("status")))).count());m.put("noShows",appointmentHistory.stream().filter(a->"NO_ASISTIO".equalsIgnoreCase(str(a.get("attendanceOutcome")))||("NO_ASISTIO".equalsIgnoreCase(str(a.get("status")))&&str(a.get("attendanceOutcome")).isBlank())).count());m.put("availableMinutes",available);m.put("usedMinutes",used);m.put("utilization",Math.round(used*1000.0/available)/10.0);m.put("production",prod);m.put("collected",paid);m.put("debt",prod.subtract(paid).max(BigDecimal.ZERO));m.put("collectionRate",prod.signum()==0?0:paid.multiply(BigDecimal.valueOf(100)).divide(prod,1,RoundingMode.HALF_UP));m.put("productionPerHour",used==0?BigDecimal.ZERO:prod.multiply(BigDecimal.valueOf(60)).divide(BigDecimal.valueOf(used),2,RoundingMode.HALF_UP));return m;}
 private boolean hasPendingBalance(ClinicalEncounter e){BigDecimal total=nvl(e.getProductionAmount());BigDecimal paid=nvl(e.getPaidAmount());return e.getProformaId()==null&&e.getTreatmentNames()!=null&&!e.getTreatmentNames().isBlank()&&total.signum()>0&&total.subtract(paid).signum()>0&&!Set.of("CANCELADA","NO_ASISTIO","REPROGRAMADA").contains(e.getStatus());}
 private Map<String,Object> pendingTreatmentView(ClinicalEncounter e){Map<String,Object> m=new LinkedHashMap<>();BigDecimal total=nvl(e.getProductionAmount()),paid=nvl(e.getPaidAmount()),balance=total.subtract(paid).max(BigDecimal.ZERO);m.put("source","ENCOUNTER");m.put("encounterId",e.getId());m.put("appointmentId",e.getAppointmentId());m.put("proformaId",e.getProformaId());m.put("proformaCode",e.getProformaCode());m.put("proformaLineReference",e.getProformaLineReference());m.put("patientId",e.getPatientId());m.put("patientName",e.getPatientName());m.put("treatmentName",e.getTreatmentNames());m.put("doctorName",e.getDoctorName());m.put("date",e.getScheduledStart());m.put("totalCost",total);m.put("paidAmount",paid);m.put("balance",balance);m.put("paymentStatus",e.getPaymentStatus());return m;}
 private void applyProformaContext(ClinicalEncounter e,Map<String,Object>a){Long proformaId=nullableLong(a.get("proformaId"));String lineRef=str(a.get("proformaLineReference"));if(proformaId==null){e.setProformaId(null);e.setProformaCode(null);e.setProformaLineReference(null);e.setPlannedTreatmentAmount(null);return;}TreatmentProforma p=proformas.findById(proformaId).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"La proforma vinculada a la cita ya no existe"));if("CANCELADA".equals(p.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"La proforma vinculada está cancelada");if(!Objects.equals(p.getPatientId(),e.getPatientId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"La proforma no pertenece al paciente de la cita");if(lineRef.isBlank())throw new ResponseStatusException(HttpStatus.CONFLICT,"La cita debe indicar qué tratamiento de la proforma realizará");ProformaLine line=p.getLines().stream().filter(l->lineRef.equals(l.getLineReference())).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"El tratamiento vinculado ya no existe en la proforma"));e.setProformaId(p.getId());e.setProformaCode(p.getCode());e.setProformaLineReference(line.getLineReference());e.setTreatmentNames(line.getTreatmentName());e.setPlannedTreatmentAmount(plannedSessionAmount(p,line));}
 private String appointmentEncounterStatus(Object value){String v=strOr(value,"PENDIENTE").toUpperCase(Locale.ROOT);return switch(v){case "COMPLETADO"->"FINALIZADA";case "CANCELADO"->"CANCELADA";case "EN_PROCESO"->"EN_ATENCION";default->v;};}
 private BigDecimal plannedSessionAmount(TreatmentProforma p,ProformaLine line){int planned=line.getPlannedSessions()==null?1:Math.max(1,line.getPlannedSessions());BigDecimal accepted=p.getAcceptedAmountForLine(line.getLineReference());return planned<=1?accepted:accepted.divide(BigDecimal.valueOf(planned),2,RoundingMode.HALF_UP);}
 private BigDecimal sessionProductionAmount(ClinicalEncounter current,ProformaLine line){TreatmentProforma p=proformas.findById(current.getProformaId()).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"La proforma vinculada ya no existe"));BigDecimal accepted=p.getAcceptedAmountForLine(line.getLineReference());int planned=line.getPlannedSessions()==null?1:Math.max(1,line.getPlannedSessions());List<ClinicalEncounter> previous=encounters.findAllByPatientIdOrderByScheduledStartDesc(current.getPatientId()).stream().filter(x->!Objects.equals(x.getId(),current.getId())&&Objects.equals(x.getProformaId(),current.getProformaId())&&Objects.equals(x.getProformaLineReference(),current.getProformaLineReference())&&"FINALIZADA".equals(x.getStatus())).toList();BigDecimal produced=previous.stream().map(ClinicalEncounter::getProductionAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);if(previous.size()>=planned-1)return accepted.subtract(produced).max(BigDecimal.ZERO);return plannedSessionAmount(p,line);}
 private ProformaLine linkedLine(ClinicalEncounter e){if(e.getProformaId()==null||e.getProformaLineReference()==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"La atención no tiene una línea de proforma vinculada");TreatmentProforma p=proformas.findById(e.getProformaId()).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"La proforma vinculada ya no existe"));return p.getLines().stream().filter(l->e.getProformaLineReference().equals(l.getLineReference())).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"El tratamiento vinculado ya no existe en la proforma"));}
 private void syncProformaProgress(ClinicalEncounter e,String lineStatus,Authentication auth){if(e.getProformaId()==null||e.getProformaLineReference()==null)return;TreatmentProforma p=proformas.findById(e.getProformaId()).orElse(null);if(p==null||"CANCELADA".equals(p.getStatus()))return;ProformaLine line=p.getLines().stream().filter(l->e.getProformaLineReference().equals(l.getLineReference())).findFirst().orElse(null);if(line==null)return;String before=p.getStatus();String effective=lineStatus;if("REALIZADO".equals(lineStatus)){long completed=encounters.findAllByPatientIdOrderByScheduledStartDesc(e.getPatientId()).stream().filter(x->Objects.equals(x.getProformaId(),p.getId())&&Objects.equals(x.getProformaLineReference(),line.getLineReference())&&"FINALIZADA".equals(x.getStatus())).count();int planned=line.getPlannedSessions()==null?1:Math.max(1,line.getPlannedSessions());effective=completed>=planned?"REALIZADO":"EN_PROCESO";}line.setTreatmentStatus(effective);if("EN_PROCESO".equals(effective))p.setStatus("EN_TRATAMIENTO");if("REALIZADO".equals(effective)){boolean allDone=p.getLines().stream().filter(l->!"CANCELADO".equals(l.getTreatmentStatus())).allMatch(l->"REALIZADO".equals(l.getTreatmentStatus()));p.setStatus(allDone?"COMPLETADA":"EN_TRATAMIENTO");}p.setUpdatedAt(LocalDateTime.now());TreatmentProforma saved=proformas.save(p);String detail=line.getTreatmentName()+": "+effective+" por cita "+e.getAppointmentId();if("REALIZADO".equals(lineStatus)&&"EN_PROCESO".equals(effective))detail+="; aún faltan sesiones planificadas";detail+="; proforma "+before+" → "+saved.getStatus();proformaHistory.save(ProformaHistory.builder().proformaId(saved.getId()).action("PROGRESO_CLINICO").detail(detail).actor(auth==null?"SYSTEM":auth.getName()).createdAt(LocalDateTime.now()).build());}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> mapList(Object v){if(!(v instanceof List<?> list))return List.of();List<Map<String,Object>> out=new ArrayList<>();for(Object item:list)if(item instanceof Map<?,?>m){Map<String,Object>x=new LinkedHashMap<>();m.forEach((k,val)->x.put(String.valueOf(k),val));out.add(x);}return out;}
 private Map<String,Object> proformaDetail(TreatmentProforma p,List<ClinicalEncounter> timeline,List<Map<String,Object>> payments,List<Map<String,Object>> appointmentHistory){Map<String,Object> out=new LinkedHashMap<>();List<ClinicalEncounter> visits=timeline.stream().filter(e->Objects.equals(e.getProformaId(),p.getId())&&e.getProformaLineReference()!=null&&!e.getProformaLineReference().isBlank()).sorted(Comparator.comparing(ClinicalEncounter::getScheduledStart,Comparator.nullsLast(Comparator.naturalOrder()))).toList();List<Map<String,Object>> pPayments=payments.stream().filter(x->Objects.equals(nullableLong(x.get("proformaId")),p.getId())).toList();List<Map<String,Object>> lineDetails=new ArrayList<>();for(ProformaLine l:p.getLines()){Map<String,Object> lm=new LinkedHashMap<>();lm.put("lineReference",l.getLineReference());lm.put("treatmentName",l.getTreatmentName());lm.put("toothZone",l.getToothZone());lm.put("quantity",l.getQuantity());lm.put("plannedSessions",l.getPlannedSessions()==null?1:l.getPlannedSessions());lm.put("unitPrice",l.getUnitPrice());lm.put("subtotal",l.getSubtotal());lm.put("acceptedAmount",p.getAcceptedAmountForLine(l.getLineReference()));lm.put("status",l.getTreatmentStatus());List<ClinicalEncounter> lineVisits=visits.stream().filter(e->Objects.equals(e.getProformaLineReference(),l.getLineReference())).toList();lm.put("completedSessions",lineVisits.stream().filter(e->"FINALIZADA".equals(e.getStatus())).count());List<Map<String,Object>> lineAppointments=appointmentHistory.stream().filter(a->Objects.equals(nullableLong(a.get("proformaId")),p.getId())&&Objects.equals(str(a.get("proformaLineReference")),l.getLineReference())).sorted(Comparator.comparing(a->dateSafe(a.get("startAt")),Comparator.nullsLast(Comparator.naturalOrder()))).toList();lm.put("appointments",lineAppointments);lm.put("visits",lineVisits.stream().map(e->visitDetail(e,pPayments)).toList());lm.put("payments",pPayments.stream().filter(x->l.getLineReference()!=null&&l.getLineReference().equals(str(x.get("proformaLineReference")))&&nullableLong(x.get("encounterId"))==null).toList());lineDetails.add(lm);}BigDecimal paid=pPayments.stream().filter(x->!"ANULADO".equalsIgnoreCase(str(x.get("paymentStatus")))).map(x->decimal(x.get("amount"))).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal performed=visits.stream().filter(e->"FINALIZADA".equals(e.getStatus())).map(ClinicalEncounter::getProductionAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);out.put("id",p.getId());out.put("code",p.getCode());out.put("status",p.getStatus());out.put("acceptedAt",p.getAcceptedAt());out.put("doctorName",p.getDoctorName());out.put("totalAmount",p.getTotalAmount());out.put("performedAmount",performed);out.put("unperformedAmount",p.getTotalAmount().subtract(performed).max(BigDecimal.ZERO));out.put("paidAmount",paid);out.put("balanceAmount",p.getTotalAmount().subtract(paid).max(BigDecimal.ZERO));out.put("lines",lineDetails);out.put("generalPayments",pPayments.stream().filter(x->str(x.get("proformaLineReference")).isBlank()).toList());out.put("visitCount",visits.size());out.put("plannedVisitCount",p.getLines().stream().filter(l->!"CANCELADO".equals(l.getTreatmentStatus())).mapToInt(l->l.getPlannedSessions()==null?1:Math.max(1,l.getPlannedSessions())).sum());out.put("completedVisitCount",visits.stream().filter(e->"FINALIZADA".equals(e.getStatus())).count());return out;}
 private Map<String,Object> visitDetail(ClinicalEncounter e,List<Map<String,Object>> payments){Map<String,Object> m=new LinkedHashMap<>();m.put("encounterId",e.getId());m.put("appointmentId",e.getAppointmentId());m.put("date",e.getScheduledStart());m.put("end",e.getScheduledEnd());m.put("doctorName",e.getDoctorName());m.put("chairName",e.getChairName());m.put("status",e.getStatus());m.put("treatmentName",e.getTreatmentNames());m.put("plannedAmount",nvl(e.getPlannedTreatmentAmount()));m.put("productionAmount",nvl(e.getProductionAmount()));m.put("paidAtVisit",nvl(e.getVisitDayPaidAmount()));m.put("payments",payments.stream().filter(x->Objects.equals(nullableLong(x.get("encounterId")),e.getId())||Objects.equals(nullableLong(x.get("appointmentId")),e.getAppointmentId())).toList());return m;}
 private LocalDateTime dateSafe(Object v){if(v==null||String.valueOf(v).isBlank())return null;try{return LocalDateTime.parse(String.valueOf(v));}catch(Exception ex){return null;}}
 private Long nullableLong(Object v){if(v==null||String.valueOf(v).isBlank()||"null".equalsIgnoreCase(String.valueOf(v)))return null;try{return v instanceof Number n?n.longValue():Long.valueOf(String.valueOf(v));}catch(Exception ex){return null;}}
 private BigDecimal decimal(Object v){if(v==null)return BigDecimal.ZERO;try{return new BigDecimal(String.valueOf(v));}catch(Exception ex){return BigDecimal.ZERO;}}
 private void ensureDoctorOwnership(ClinicalEncounter encounter,Authentication auth){if(has(auth,"DOCTOR")&&!belongsToDoctor(encounter,auth))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Solo puedes gestionar tus propias atenciones");}
 private boolean belongsToDoctor(ClinicalEncounter encounter,Authentication auth){String email=normalizeEmail(encounter.getDoctorAccountEmail());if(email!=null)return email.equalsIgnoreCase(auth.getName());String fullName=auth.getDetails()==null?"":auth.getDetails().toString();return encounter.getDoctorName()!=null&&fullName.equalsIgnoreCase(encounter.getDoctorName());}
 private String normalizeEmail(String value){return value==null||value.isBlank()?null:value.trim().toLowerCase();}
 private double change(BigDecimal current,BigDecimal previous){if(previous==null||previous.signum()==0)return current!=null&&current.signum()>0?100:0;return current.subtract(previous).multiply(BigDecimal.valueOf(100)).divide(previous.abs(),1,RoundingMode.HALF_UP).doubleValue();}
 private double percentage(BigDecimal value,BigDecimal goal){if(goal==null||goal.signum()<=0)return 0;return value.multiply(BigDecimal.valueOf(100)).divide(goal,1,RoundingMode.HALF_UP).doubleValue();}
 private ClinicalEncounter find(Long id){return encounters.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Atención no encontrada"));}
 private String treatmentCategory(String category,String specialty){String raw=(category==null||category.isBlank())?specialty:category;if(raw==null)return "GENERALES";String n=raw.trim().toUpperCase(Locale.ROOT);if(n.contains("ENDO"))return "ENDODONCIA";if(n.contains("ORTO"))return "ORTODONCIA";if(n.equals("GENERALES")||n.contains("GENERAL")||n.contains("CIRUG")||n.contains("REHABIL"))return "GENERALES";throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Categoría permitida: ENDODONCIA, ORTODONCIA o GENERALES");}
 private boolean has(Authentication a,String r){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_"+r));}
 private BigDecimal nvl(BigDecimal v){return v==null?BigDecimal.ZERO:v;}
 private String str(Object v){return v==null?"":String.valueOf(v);}
 private String strOr(Object v,String d){String s=str(v);return s.isBlank()?d:s;}
 private Long longValue(Object v){return v instanceof Number n?n.longValue():Long.valueOf(String.valueOf(v));}
 private Integer intValue(Object v,int d){return v==null?d:(v instanceof Number n?n.intValue():Integer.valueOf(String.valueOf(v)));}
 private LocalDateTime date(Object v){return LocalDateTime.parse(String.valueOf(v));}
 private String q(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}
 private ClinicalEncounter copy(ClinicalEncounter e){return ClinicalEncounter.builder().id(e.getId()).code(e.getCode()).appointmentId(e.getAppointmentId()).patientId(e.getPatientId()).patientName(e.getPatientName()).doctorId(e.getDoctorId()).doctorName(e.getDoctorName()).doctorAccountEmail(e.getDoctorAccountEmail()).chairId(e.getChairId()).chairName(e.getChairName()).specialty(e.getSpecialty()).scheduledStart(e.getScheduledStart()).scheduledEnd(e.getScheduledEnd()).arrivedAt(e.getArrivedAt()).actualStart(e.getActualStart()).actualEnd(e.getActualEnd()).status(e.getStatus()).treatmentNames(e.getTreatmentNames()).durationMinutes(e.getDurationMinutes()).proformaId(e.getProformaId()).proformaCode(e.getProformaCode()).proformaLineReference(e.getProformaLineReference()).plannedTreatmentAmount(e.getPlannedTreatmentAmount()).productionAmount(e.getProductionAmount()).paidAmount(e.getPaidAmount()).visitDayPaidAmount(e.getVisitDayPaidAmount()).paymentStatus(e.getPaymentStatus()).notes(e.getNotes()).labRepetition(e.getLabRepetition()).correctiveTreatment(e.getCorrectiveTreatment()).postTreatmentEmergency(e.getPostTreatmentEmergency()).followUpCompleted(e.getFollowUpCompleted()).satisfactionScore(e.getSatisfactionScore()).createdAt(e.getCreatedAt()).updatedAt(e.getUpdatedAt()).build();}
 public record TreatmentAssignmentRequest(@NotBlank String treatmentName,@NotNull @DecimalMin("0.01") BigDecimal totalCost){} public record FinishRequest(String treatmentNames,BigDecimal productionAmount,String notes,Boolean labRepetition,Boolean correctiveTreatment,Boolean postTreatmentEmergency,Boolean followUpCompleted,String reason){} public record PaymentLink(BigDecimal amount,String reference,LocalDateTime paidAt){} public record AuditRequest(String module,String entityType,String entityId,String action,Object before,Object after,String reason){}
